# ---------------------------------------------------------------- reshape.py
FILES['flowtrail/reshape.py'] = 'The path math for reshaping arcs: smoothing, matching a hand-drawn stroke, keeping keys pinned, keeping spacing, and choosing as few keys as possible. Pure Python with no Maya, tested in `tests/test_reshape.py`.'
NOTES['flowtrail/reshape.py'] = {
    'dist': 'Distance between two points (2D or 3D).',
    'lerp': 'Point between `a` and `b` at fraction `f`.',
    'arc_lengths': 'Running distance along a polyline: `[0, d1, d1+d2, ...]`. Many functions use it to place things "at 40% of the path".',
    'point_at': 'The point at a given distance along a polyline. `bisect` finds the segment quickly in the sorted running distances, then it interpolates inside that segment.',
    'is_closed': 'True when the path ends where it starts (within 1% of its length): a loop.',
    '_gain': 'How much of each wave the smoothing keeps: everything up to half the cutoff, then a soft cosine fade to nothing. A hard cut would make the path ripple ("ringing").',
    '_lowpass_closed': 'Smoothing for a **loop**: describe the path as a sum of waves that repeat around the loop (a Fourier series), keep the slow ones and drop the fast ones. Because the waves wrap around, the seam is smoothed too.',
    '_lowpass_open': 'Smoothing for an **open** path: take the straight line between the two ends, describe the difference from it as a sum of sine waves (which are 0 at both ends), keep the slow ones. The ends never move.',
    'lowpass': 'Removes wobble from a path **without shrinking its arcs**, which plain neighbor averaging does. Strength sets the shortest wave that survives, on a log scale. Each axis (x, y, z) is filtered separately.',
    '_falloff': 'Cosine falloff from 1 at distance 0 to 0 at `width`.',
    'pin_correct': 'After smoothing, puts the **pinned** frames (keys you want to keep, and the ends) back exactly where they were. Each pin\'s correction fades out smoothly toward the next pin, so the rest of the new shape is kept.',
    'spacing_params': 'Where each frame sits along the path, from 0 to 1: by real distance (keep spacing) or evenly.',
    'respace': 'Slides the frames along the new path so the **spacing** is kept from the original (your eases survive) or made even. A hold (no motion between pins) stays a hold. In "free" mode nothing is moved.',
    'smooth_path': 'The full smoothing step used by the Smooth button and brush: detect loop, low-pass, put pins back, fix spacing. Returns the new points and whether it was a loop.',
    'clean_stroke': 'Cleans a raw mouse stroke: drops duplicate points, resamples it evenly, closes it if its ends nearly touch (hand-drawn loops rarely close exactly), and smooths it a little.',
    'sample_stroke': 'Points on a stroke at given 0-1 positions.',
    '_passes': 'For one screen point: the nearest frame of **each separate time** the trail passes under it. A loop passes under its seam point twice (start and end).',
    'pick_span': 'Decides which part of the trail a sketched stroke replaces: from the frame nearest the stroke start to the frame nearest its end. If the trail passes there more than once, it takes the widest span, so drawing from a loop\'s seam back to the seam replaces the whole loop. Strokes drawn backwards in time are handled.',
    'stroke_is_forward': 'Was the stroke drawn in the same direction as time? Compares the stroke with the trail both ways.',
    'choose_frames': 'Key reduction: the fewest frames such that interpolating between them stays within `tol` of the wanted offsets. It splits each segment at its worst frame until every frame is close enough (the Ramer-Douglas-Peucker idea, applied over time). Required frames (ends, existing keys) are always kept.',
    'worst_frames': 'After writing keys and reading the real result back, the worst frame of each stretch that is still off; the adaptive mode adds keys there.',
    'delta_at': 'The offset at any time, interpolated between the sampled times.',
}
LINES['flowtrail/reshape.py'] = [
    ("i = bisect.bisect_right(cum, s) - 1", '`bisect` does a binary search on the sorted running distances: the segment that contains distance `s`.'),
    ("return math.cos(math.pi * (f - 0.5)) ** 2 if f < 1.0 else 0.0", 'Cosine-squared fade from 1 to 0 between half the cutoff and the cutoff.'),
    ("a = sum(x * cos_t[(m * i) % n] for i, x in enumerate(v)) * g", 'How much of the m-th repeating wave is in the path (its cosine part); `g` already includes the fade.'),
    ("line = [v[0] + (v[-1] - v[0]) * i / float(last) for i in range(last + 1)]", 'The straight line between the ends. Only the difference from it is filtered, so the ends stay fixed.'),
    ("wave = MIN_WAVE * (max(longest, MIN_WAVE) / MIN_WAVE) ** strength", 'Log scale between the shortest wave (4 samples) and the longest the path can hold.'),
    ("out[i] = tuple(n - x * fa - y * fb for n, x, y in zip(new[i], ra, rb))", 'Subtract each nearby pin\'s error, weighted by how close this frame is to that pin.'),
    ("continue    # a hold: stays a hold", 'No distance between these pins in the original: do not spread frames out.'),
    ("if a > b:   # drawn against time", 'The stroke started near a later frame than it ended: swap.'),
    ("stack = list(zip(ordered[:-1], ordered[1:]))", 'Segments still to check. Using a stack instead of recursion avoids recursion limits on long ranges.'),
    ("err = dist(deltas[i], lerp(deltas[a], deltas[b], f))", 'How far straight interpolation between the two kept frames is from what is wanted at frame `i`.'),
]

# ---------------------------------------------------------------- draw.py
FILES['flowtrail/draw.py'] = 'Turns a trail\'s cached positions into the point and color arrays the viewport plugin draws. It runs during viewport drawing, so it only uses the API (no `maya.cmds`) and does as little work as possible.'
NOTES['flowtrail/draw.py'] = {
    '_mix': 'Blend between two colors.',
    'ramp': 'Speed color: maps 0 to 1 onto blue → green → yellow → red, using the stops in `RAMP`.',
    '_color': 'An `MColor` from RGB and alpha.',
    '_is_frame': 'True for whole frames (sub-frame samples are only for a smoother line).',
    '_points': 'A list of tuples as an `MPointArray`, the type the viewport draws.',
    'Packet': 'Everything needed to draw one trail: lines, frame dots, keys, selected keys, current frame, labels, ghost, ticks, previews, and pick points for clicking. The plugin only reads it.',
    'Packet.__init__': 'Every field starts empty; `build` and `dynamic` fill what is needed.',
    'build': 'Builds the parts that only change when the data, the settings or the current frame change (so they can be cached): the path line (split where samples are missing), frame dots, keys (yellow on the layer being edited, grey on other layers, cyan when selected), labels, the current frame, the ghost of another layer, the retime preview, and the points the edit tool can click. Positions go through `display_xformer` so the trail can be shown in world, camera or object space.',
    'build.to_display': 'Moves a world position into the chosen display space at time `t`.',
    'build.speed_norm': 'Speed of the frame relative to the fast end of the shot (95th percentile, so one spike does not wash out the colors).',
    'build.rgb_at': 'Trail color at time `t`: speed color, or a dimmer color for the past and the trail color for the future.',
    'build.alpha_at': 'Fade with distance from the current frame, if fading is on.',
    'dynamic': 'Parts recomputed on every draw because they depend on the camera or on interaction: the reshape preview and stroke, the live position (red dot when the control was moved but not keyed), and the spacing ticks, which are drawn sideways to the path **as seen from the camera** (path direction crossed with the view direction).',
}
LINES['flowtrail/draw.py'] = [
    ("top = ordered[int(0.95 * (len(ordered) - 1))] or max(ordered) or 1.0", 'Normalize by the 95th percentile speed, not the maximum, so one very fast frame does not make everything else look blue.'),
    ("on_edit = edit_layer is None or edit_layer in layers or \\", 'Keys on the layer you are editing are drawn in the main key color; keys that live only on other layers are grey.'),
    ("side = (nxt - prev) ^ vd", '`^` between `MVector`s is the cross product: perpendicular to both the path direction and the view direction, so the tick always faces the camera.'),
    ("side *= dist * 0.012 * pk.tick_size", 'Scale the tick with distance from the camera so it keeps the same size on screen.'),
]

